mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM tbl_dim_customer
    WHERE organization_id = #{organizationId}
      AND deleted_at IS NULL
      AND LOWER(customer_alias) = LOWER(#{customerAlias})

          AND customer_id <> #{excludeCustomerId}

)

SELECT EXISTS( SELECT 1 FROM tbl_dim_customer WHERE deleted_at IS NULL AND LOWER(customer_code) = LOWER(#{customerCode})
AND customer_id <> #{excludeCustomerId}
)
